// Auth0 Client-Initiated Backchannel Authentication: ask the user on their phone
// (Auth0 Guardian push) to approve one step, then poll for the answer.
import { need } from "./env.js";

const domain = () => need("AUTH0_DOMAIN").replace(/^https?:\/\//, "").replace(/\/$/, "");
const client = () => ({ client_id: need("AUTH0_CLIENT_ID"), client_secret: need("AUTH0_CLIENT_SECRET") });

async function post(path: string, body: Record<string, string>) {
  const res = await fetch(`https://${domain()}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(body),
  });
  return { status: res.status, json: (await res.json().catch(() => ({}))) as Record<string, any> };
}

// binding_message: max 64 chars, letters, digits, spaces and +-_.,:#
export function bindingMessage(text: string) {
  return text.replace(/₹/g, "INR ").replace(/[^A-Za-z0-9 +\-_.,:#]/g, "").replace(/\s+/g, " ").trim().slice(0, 64);
}

export async function startApproval(userSub: string, message: string) {
  const { status, json } = await post("/bc-authorize", {
    ...client(),
    scope: "openid",
    login_hint: JSON.stringify({ format: "iss_sub", iss: `https://${domain()}/`, sub: userSub }),
    binding_message: bindingMessage(message),
    requested_expiry: "300",
  });
  if (status !== 200) throw new Error(`CIBA start failed: ${json.error} ${json.error_description ?? ""}`);
  return { authReqId: json.auth_req_id as string, expiresIn: json.expires_in as number, interval: json.interval as number };
}

export type ApprovalState = "pending" | "approved" | "denied" | "expired";

export async function checkApproval(authReqId: string): Promise<ApprovalState> {
  const { status, json } = await post("/oauth/token", {
    ...client(),
    grant_type: "urn:openid:params:grant-type:ciba",
    auth_req_id: authReqId,
  });
  if (status === 200 && json.access_token) return "approved";
  if (json.error === "authorization_pending" || json.error === "slow_down") return "pending";
  if (json.error === "expired_token") return "expired";
  if (json.error === "access_denied") {
    // Auth0 uses access_denied for both "denied" and "expired"
    return /expired/i.test(json.error_description ?? "") ? "expired" : "denied";
  }
  throw new Error(`CIBA check failed: ${json.error} ${json.error_description ?? ""}`);
}
// Sends one test approval push to a user's phone and waits for the answer.
import { startApproval, checkApproval } from "../src/lib/ciba.js";

const sub = process.argv[2];
if (!sub) throw new Error("usage: tsx scripts/ciba-test.ts <auth0 user sub>");
const req = await startApproval(sub, "Sloth Errands test push");
console.log(`Push sent, expires in ${req.expiresIn}s`);
const until = Date.now() + req.expiresIn * 1000;
while (Date.now() < until) {
  await new Promise((r) => setTimeout(r, (req.interval || 5) * 1000));
  const state = await checkApproval(req.authReqId);
  console.log(state);
  if (state !== "pending") break;
}
import "./env";
import { Auth0Client } from "@auth0/nextjs-auth0/server";

// Reads AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET, AUTH0_SECRET and APP_BASE_URL
export const auth0 = new Auth0Client();
import { NextResponse, type NextRequest } from "next/server";
import { auth0 } from "./lib/auth0";

// Every page needs a signed-in user. The home page shows its own sign-in screen instead.
export async function proxy(request: NextRequest) {
  const authRes = await auth0.middleware(request);
  const url = new URL(request.url);
  if (url.pathname.startsWith("/auth") || url.pathname === "/") return authRes;

  const session = await auth0.getSession(request);
  if (session) return authRes;
  if (url.pathname.startsWith("/api/")) {
    return NextResponse.json({ error: "Sign in first" }, { status: 401 });
  }
  const login = new URL("/auth/login", url.origin);
  login.searchParams.set("returnTo", url.pathname);
  return NextResponse.redirect(login);
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)"],
};
