  "name": "web",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start"
  },
  "dependencies": {
    "@auth0/nextjs-auth0": "^4.33.0",
    "@phosphor-icons/react": "^2.1.10",
    "@temporalio/client": "^1.24.0",
    "@temporalio/common": "1.24.0",
    "dotenv": "^18.0.9",
