cd /home/anish-kumar/Code/hacktoberfest/week4/still-here; mkdir -p fga; cat > fga/model.fga <<'EOF'
# Still Here authorization model (Auth0 FGA / OpenFGA DSL).
# The JSON form that is actually uploaded lives in lib/fga.ts (MODEL).
model
  schema 1.1

type user

type vault
  relations
    define owner: [user]
    # Written as vault:<id>#released@user:* by code, only after both trusted people approve.
    # A check-in from the owner deletes it again.
    define released: [user:*]

type note
  relations
    define vault: [vault]
    define owner: owner from vault
    define reader: [user]
    define can_read: owner or (reader and released from vault)

type letter
  relations
    define vault: [vault]
    define owner: owner from vault
    define recipient: [user]
    define can_read: owner or (recipient and released from vault)
EOF
cat > lib/fga.ts <<'EOF'
// Auth0 FGA decides who may read which note or letter. The same code runs against a local
// OpenFGA server (no credentials) or Auth0 FGA (client credentials), picked by env vars.
import { CredentialsMethod, OpenFgaClient, type TupleKey } from "@openfga/sdk";
import { maybe, need } from "./env";

// JSON form of fga/model.fga
export const MODEL = {
  schema_version: "1.1",
  type_definitions: [
    { type: "user" },
    {
      type: "vault",
      relations: { owner: { this: {} }, released: { this: {} } },
      metadata: {
        relations: {
          owner: { directly_related_user_types: [{ type: "user" }] },
          released: { directly_related_user_types: [{ type: "user", wildcard: {} }] },
        },
      },
    },
    ...(["note", "letter"] as const).map((type) => {
      const holder = type === "note" ? "reader" : "recipient";
      return {
