      for (const item of s.items ?? []) dropped.push({ item, why: `unknown audience ${audience}` });
      continue;
    }
    const items: HandbookItem[] = [];
    for (const item of s.items ?? []) {
      const sources = (item.sources ?? []).map((x) => String(x).replace(/[[\]]/g, ""));
