9	import { getPeople, getVaultById } from "./vault";
10	
11	export type HandbookItem = { text: string; sources: string[] };
12	export type HandbookSection = { audience: string; title: string; items: HandbookItem[] };
13	
14	const SYSTEM = `You prepare a practical handbook for the family of a person who has died.
15	You are given that person's documents, each with a label like [d1], and the people the handbook is for.
16	Write what each person needs to DO or KNOW: what exists, where it is, deadlines, amounts, phone numbers,
17	what renews and must be cancelled or kept. Use only facts in the documents. Do not invent anything.
18	No condolences, no feelings, no advice beyond what the documents support.
19	Every item must cite the labels of the documents it comes from in "sources".
20	Audience is the key of one person, or "everyone" for items that apply to all of them.
21	Reply with JSON only:
22	{"sections": [{"audience": string, "title": string, "items": [{"text": string, "sources": string[]}]}]}`;
23	
24	export async function runHandbook(opts: { vaultId: string; model?: ModelKey; maxTokens?: number }) {
25	  const vault = await getVaultById(opts.vaultId);
26	  if (!vault) throw new Error("no vault");
27	  const people = (await getPeople(vault.id)).filter((p) => p.role === "trusted");
28	  const docs = await sql<{ id: string; kind: string; title: string; body: string }[]>`
29	    select id, kind, title, body from documents where vault_id = ${vault.id} order by created_at`;
30	  const labels = new Map(docs.map((d, i) => [`d${i + 1}`, d]));
31	  const keys = new Map(people.map((p) => [p.name.toLowerCase(), p]));
32	
33	  const res = await chat({
34	    job: "handbook",
35	    vaultId: vault.id,
36	    model: opts.model,
37	    json: true,
38	    maxTokens: opts.maxTokens ?? 8000,
39	    temperature: 0.2,
40	    messages: [
41	      { role: "system", content: SYSTEM },
42	      {
43	        role: "user",
44	        content:
45	          `The person who died: ${vault.owner_name}.\n` +
46	          `People (key: who):\n${people.map((p) => `- ${p.name.toLowerCase()}: ${p.name}, ${p.relation}`).join("\n")}\n` +
47	          `- everyone: all of them\n\nDocuments:\n\n` +
48	          [...labels].map(([l, d]) => `[${l}] (${d.kind}) ${d.title}\n${d.body}`).join("\n\n"),
49	      },
50	    ],
51	  });
52	
53	  const raw = parseJson<{ sections?: HandbookSection[] }>(res.text).sections ?? [];
54	  // Code keeps only what it can check: a known audience, and sources that are real documents.
55	  const sections: HandbookSection[] = [];
56	  const dropped: { item: HandbookItem; why: string }[] = [];
57	  for (const s of raw) {
58	    const audience = String(s.audience ?? "").toLowerCase();
59	    if (audience !== "everyone" && !keys.has(audience)) {
60	      for (const item of s.items ?? []) dropped.push({ item, why: `unknown audience ${audience}` });
61	      continue;
62	    }
63	    const items: HandbookItem[] = [];
64	    for (const item of s.items ?? []) {
65	      const sources = (item.sources ?? []).map((x) => String(x).replace(/[[\]]/g, ""));
66	      if (!item.text?.trim() || !sources.length) dropped.push({ item, why: "no source" });
67	      else if (!sources.every((x) => labels.has(x))) dropped.push({ item, why: "source not a document" });
68	      else items.push({ text: item.text.trim(), sources: sources.map((x) => labels.get(x)!.id) });
69	    }
70	    if (items.length) sections.push({ audience, title: String(s.title ?? "").trim() || "Notes", items });
71	  }
72	
73	  const docx = await renderDocx(vault.owner_name, sections, docs, people);
74	  const [row] = await sql`
75	    insert into handbooks (vault_id, model, sections, dropped, docx, usage_id)
76	    values (${vault.id}, ${opts.model ?? "default"}, ${sql.json(sections as never)}, ${sql.json(dropped as never)}, ${docx}, ${res.usageId})
77	    returning id`;
78	  await audit(vault.id, "model", "handbook_written", {
79	    handbook_id: row.id,
80	    model: opts.model,
81	    items: sections.reduce((n, s) => n + s.items.length, 0),
82	    dropped: dropped.length,
83	    cost_usd: res.costUsd,
84	  });
85	  return { id: row.id as string, sections, dropped, docx, usage: res };
86	}
