88	async function renderDocx(
89	  owner: string,
90	  sections: HandbookSection[],
91	  docs: { id: string; title: string }[],
92	  people: { name: string; relation: string }[],
93	) {
94	  const docTitle = new Map(docs.map((d) => [d.id, d.title]));
95	  const who = (audience: string) => {
96	    if (audience === "everyone") return "For everyone";
97	    const p = people.find((x) => x.name.toLowerCase() === audience);
98	    return p ? `For ${p.name} (${p.relation})` : audience;
99	  };
100	  // Group by audience: "everyone" first, then each person
101	  const order = ["everyone", ...people.map((p) => p.name.toLowerCase())];
102	  const sorted = [...sections].sort((a, b) => order.indexOf(a.audience) - order.indexOf(b.audience));
103	
104	  const children: Paragraph[] = [
105	    new Paragraph({ text: `What my family needs to know`, heading: HeadingLevel.TITLE }),
106	    new Paragraph({
107	      children: [new TextRun({ text: `${owner}'s handbook, drafted from his documents by Still Here.`, italics: true })],
108	    }),
109	    new Paragraph({ text: "" }),
110	  ];
111	  let lastAudience = "";
112	  for (const s of sorted) {
113	    if (s.audience !== lastAudience) {
114	      children.push(new Paragraph({ text: who(s.audience), heading: HeadingLevel.HEADING_1 }));
115	      lastAudience = s.audience;
116	    }
117	    children.push(new Paragraph({ text: s.title, heading: HeadingLevel.HEADING_2 }));
118	    for (const item of s.items) {
119	      children.push(
