.after { margin: 140px 0 0; scroll-margin-top: 20px; }
.after-head { display: flex; justify-content: space-between; align-items: end; gap: 24px; flex-wrap: wrap; margin-bottom: 26px; }
.who { display: flex; gap: 8px; flex-wrap: wrap; }
