.peek:hover { background: #e4d6c0; }
.peek:focus-visible { outline-color: var(--marigold-deep); }
.qa { padding: 40px; }
.qa .q { color: var(--soft); font-size: 15px; }
.qa .a { font-size: 21px; margin: 10px 0 16px; }
.qa .a.dim { color: var(--soft); font-family: var(--serif); font-style: italic; font-size: 26px; }
.src { display: inline-flex; gap: 8px; align-items: center; font-size: 14px; color: var(--marigold); border-bottom: 1px solid currentColor; margin: 0 14px 8px 0; }
.gate { margin-top: 14px; font-size: 14px; color: var(--soft); display: flex; gap: 8px; align-items: flex-start; }
.gate svg { margin-top: 3px; flex: none; }
.ask label { font-size: 14px; color: var(--soft); }
.ask-row { display: flex; margin-top: 8px; }
.ask-row input { flex: 1; min-width: 0; min-height: 50px; background: var(--night); border: 1px solid var(--line); border-right: 0; padding: 0 14px; font-size: 16px; }
.ask-row button { width: 54px; min-height: 50px; border: 0; background: var(--marigold); color: var(--night); display: grid; place-items: center; cursor: pointer; transition: background .2s; }
.ask-row button:hover { background: var(--marigold-light); }
.ask-row button:disabled { background: var(--line); color: var(--soft); cursor: not-allowed; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0 26px; }
.chips button { min-height: 40px; padding: 0 12px; background: var(--night-2); border: 0; color: var(--text); font-size: 14px; cursor: pointer; transition: background .2s; }
.chips button:hover { background: var(--night-3); }
.result .a { animation: rise .5s ease-out both; }

