.numbers div + div { border-left: 1px solid var(--line); }
.numbers b { display: block; font-family: var(--serif); font-weight: 400; font-size: clamp(44px, 5vw, 64px); line-height: 1; color: var(--marigold-light); margin-bottom: 12px; font-variant-numeric: tabular-nums; }
.numbers span { color: var(--soft); font-size: 15px; }

