.form .field { margin-top: 0; background: var(--night); }
.form textarea.field { padding: 12px 14px; min-height: 120px; resize: vertical; line-height: 1.5; }
.form select.field { appearance: none; }
.form .two { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.form .three { display: grid; grid-template-columns: 1fr 1fr 1.4fr; gap: 14px; }
.checks { display: flex; gap: 18px; flex-wrap: wrap; font-size: 15px; }
.checks label { display: flex; gap: 8px; align-items: center; color: var(--text); min-height: 44px; }
.checks input { width: 18px; height: 18px; accent-color: var(--marigold); }
.note-msg { font-size: 14px; color: var(--marigold-light); min-height: 20px; }
.err { color: #f0a58c; font-size: 14px; }
.inline { display: inline; }
.link-btn { background: none; border: 0; color: var(--soft); text-decoration: underline; cursor: pointer; font-size: 14px; min-height: 44px; padding: 0 4px; }
.link-btn:hover { color: var(--text); }

/* The check-in answer page */
.checkin-page { min-height: 70vh; display: grid; align-content: center; padding: 40px 0 80px; }
.checkin-page .ask-line { font-size: clamp(56px, 10vw, 140px); }
.checkin-page form { max-width: 440px; margin-top: 44px; }

@media (max-width: 960px) {
