// What the switch looks like right now, for the timeline page.
import { sql } from "./db";
import { getPeople, getSwitch } from "./vault";

export type VaultStatus = Awaited<ReturnType<typeof vaultStatus>>;

export async function vaultStatus(vaultId: string) {
  const [s, people, approvals, audit, checkins] = await Promise.all([
    getSwitch(vaultId),
    getPeople(vaultId),
    sql`select person_id, round, status, sent_at, decided_at from approvals where vault_id = ${vaultId} order by round desc, sent_at`,
    sql`select id, at, actor, action, detail from audit_log where vault_id = ${vaultId} order by id desc limit 50`,
import type postgres from "postgres";
import { sql } from "./db";

// Append-only. A trigger on audit_log rejects any UPDATE or DELETE.
export async function audit(vaultId: string | null, actor: string, action: string, detail: Record<string, unknown> = {}, db: postgres.Sql | postgres.TransactionSql = sql) {
  await db`insert into audit_log (vault_id, actor, action, detail) values (${vaultId}, ${actor}, ${action}, ${sql.json(detail as never)})`;
}

