  handbook: (maybe("HANDBOOK_MODEL") as ModelKey) ?? "gpt-oss-120b",
  eval: "gpt-oss-120b",
};

function endpoint(provider: Provider) {
  if (provider === "groq") return { base: "https://api.groq.com/openai/v1", key: need("GROQ_API_KEY") };
