    insert into handbooks (vault_id, model, sections, dropped, docx, usage_id)
    values (${vault.id}, ${opts.model ?? "default"}, ${sql.json(sections as never)}, ${sql.json(dropped as never)}, ${docx}, ${res.usageId})
    returning id`;
