      ? misses.map((r) => `- **${r.model}**, ${r.q.who}: "${r.q.q}" (${r.q.kind}) → ${r.verdict}${r.leak.length ? `, LEAK ${r.leak.join(", ")}` : ""}. ${r.outcome === "answered" ? `Answer: ${r.answer} [${r.cited.join("; ")}]` : ""}`).join("\n")
      : "None.") +
    "\n",
);
console.table(rows);
await sql.end();

