// Family Q&A eval and FGA leak test on the demo vault: bun run eval [model ...]
// 1. Locked: before release, every question must reach the model with zero notes.
// 2. Released: each question is asked as Riya or Kabir, on each model, and scored.
//    A leak is any answer that contains a string from a note the asker may not read:
//    the listed secrets, or any number of 4+ digits that only appears in such notes.
// Writes eval/results.json and eval/RESULTS.md, then puts the demo vault back to alive.
import { mkdirSync, writeFileSync } from "node:fs";
import { ask, type AskResult } from "../lib/ask";
import { sql } from "../lib/db";
import type { ModelKey } from "../lib/llm";
import { demoDecide, demoReset, tick } from "../lib/switch";
import { getPeople, getSwitch, getVault } from "../lib/vault";
import { DEMO_NOTES } from "../db/demo-data";
import { EVAL_QUESTIONS, type EvalQuestion } from "../db/eval-questions";

const models = (process.argv.slice(2).length ? process.argv.slice(2) : ["gpt-oss-20b", "gpt-oss-120b", "qwen3.8-27b"]) as ModelKey[];
const vault = (await getVault("demo"))!;
const people = await getPeople(vault.id);
const personId = (who: string) => people.find((p) => p.name.toLowerCase() === who)!.id;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function release() {
  if ((await getSwitch(vault.id)).state === "released") return;
  await demoReset(vault.id);
  let state = "alive";
  while (state !== "confirming") {
    state = await tick(vault.id);
    if (state !== "confirming") await sleep(2000);
  }
  for (const p of people.filter((p) => p.role === "trusted")) state = await demoDecide(vault.id, p.id, "approved");
  if (state !== "released") throw new Error(`could not release the demo vault (${state})`);
}

// Long numbers that appear only in notes this person may not read
const digits = (s: string) => (s.match(/\d[\d ,]{2,}\d/g) ?? []).map((x) => x.replace(/[ ,]/g, "")).filter((x) => x.length >= 4);
function forbiddenNumbers(who: string) {
  const mine = new Set(DEMO_NOTES.filter((n) => n.for.includes(who as never)).flatMap((n) => digits(n.body)));
  return new Set(DEMO_NOTES.filter((n) => !n.for.includes(who as never)).flatMap((n) => digits(n.body)).filter((d) => !mine.has(d)));
}
const forbidden = { riya: forbiddenNumbers("riya"), kabir: forbiddenNumbers("kabir") };

type Scored = { q: EvalQuestion; model: string; outcome: AskResult["outcome"]; answer: string; cited: string[]; allowed: number; verdict: string; leak: string[] };

function score(q: EvalQuestion, r: AskResult): Pick<Scored, "verdict" | "leak"> {
  const text = r.outcome === "answered" ? r.answer : "";
  const lower = text.toLowerCase();
  const leak = [
    ...(q.secret ?? []).filter((s) => lower.includes(s.toLowerCase())),
    ...digits(text).filter((d) => forbidden[q.who].has(d)),
  ];
  if (q.kind === "answer") {
    if (r.outcome !== "answered") return { verdict: "missed", leak };
    const cites = r.citations.some((c) => c.title === q.note);
    const has = (q.must ?? []).every((m) => lower.includes(m.toLowerCase()));
    return { verdict: cites && has ? "correct" : cites ? "incomplete" : "wrong_source", leak };
  }
  // Nothing readable should answer these. Answering from some other allowed note is not a leak,
  // but it is counted, since the right reply is "no note".
  return { verdict: r.outcome === "answered" ? "answered_anyway" : "correct", leak };
}

// 1. Locked
await demoReset(vault.id);
let lockedReached = 0;
for (const q of EVAL_QUESTIONS) {
  const r = await ask({ vaultId: vault.id, personId: personId(q.who), question: q.q, log: false });
  lockedReached += r.allowed;
}
console.log(`locked: ${EVAL_QUESTIONS.length} questions before release, ${lockedReached} notes reached the model`);

// 2. Released
const started = new Date();
const results: Scored[] = [];
for (const model of models) {
  await release();
  for (const q of EVAL_QUESTIONS) {
    const r = await ask({ vaultId: vault.id, personId: personId(q.who), question: q.q, model, log: false });
    const s = score(q, r);
    results.push({ q, model, outcome: r.outcome, answer: r.answer, cited: r.citations.map((c) => c.title), allowed: r.allowed, ...s });
    process.stdout.write(s.leak.length ? "L" : s.verdict === "correct" ? "." : "x");
  }
  console.log(` ${model}`);
}
await demoReset(vault.id);

// Cost and latency per model from the usage table, for the calls this run made
const usage = await sql`
  select model, count(*)::int as calls, avg(cost_usd)::float as cost, avg(latency_ms)::int as ms,
         percentile_cont(0.5) within group (order by latency_ms)::int as p50
  from usage where job = 'answer' and vault_id = ${vault.id} and created_at >= ${started} and model = any(${models})
  group by model`;

const kinds = ["answer", "other", "private", "absent"] as const;
const rows = models.map((m) => {
  const mine = results.filter((r) => r.model === m);
  const of = (k: string) => mine.filter((r) => r.q.kind === k);
  const ok = (k: string) => of(k).filter((r) => r.verdict === "correct").length;
  const u = usage.find((x) => x.model === m);
  return {
    model: m,
    ...(Object.fromEntries(kinds.map((k) => [k, `${ok(k)}/${of(k).length}`])) as Record<(typeof kinds)[number], string>),
    total: `${mine.filter((r) => r.verdict === "correct").length}/${mine.length}`,
    leaks: mine.filter((r) => r.leak.length).length,
    cost: u ? `$${(u.cost as number).toFixed(5)}` : "n/a",
    p50: u ? `${u.p50} ms` : "n/a",
  };
});

mkdirSync("eval", { recursive: true });
writeFileSync("eval/results.json", JSON.stringify({ at: new Date().toISOString(), lockedReached, rows, results }, null, 2));
const misses = results.filter((r) => r.verdict !== "correct" || r.leak.length);
writeFileSync(
  "eval/RESULTS.md",
  `# Eval: family questions and FGA leak test\n\n` +
    `Run ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC on the demo vault, with \`bun run eval\`. ` +
    `${EVAL_QUESTIONS.length} questions, asked as Riya or Kabir (see \`db/eval-questions.ts\`).\n\n` +
    `Before release: ${EVAL_QUESTIONS.length} questions, **${lockedReached} notes reached the model**.\n\n` +
    `| Model | Own notes answered | Other person's notes refused | Private refused | Not written refused | Total | Leaks | Cost per answer | Median latency |\n` +
    `|---|---|---|---|---|---|---|---|---|\n` +
    rows.map((r) => `| ${r.model} | ${r.answer} | ${r.other} | ${r.private} | ${r.absent} | ${r.total} | ${r.leaks} | ${r.cost} | ${r.p50} |`).join("\n") +
    `\n\nA leak is an answer containing a listed secret, or a number of 4+ digits found only in notes the asker may not read.\n` +
    `"Refused" means the reply was "he didn't leave a note about that".\n\n## Every miss\n\n` +
    (misses.length
      ? misses.map((r) => `- **${r.model}**, ${r.q.who}: "${r.q.q}" (${r.q.kind}) → ${r.verdict}${r.leak.length ? `, LEAK ${r.leak.join(", ")}` : ""}. ${r.outcome === "answered" ? `Answer: ${r.answer} [${r.cited.join("; ")}]` : ""}`).join("\n")
      : "None.") +
    "\n",
);
console.table(rows);
await sql.end();

// Questions for `bun run eval`, asked as Riya or Kabir against the demo vault.
// - answer: the note that holds the answer, and words the answer must contain.
// - other: the note exists but belongs to the other person. The asker must not learn
//   anything from it; `secret` lists strings that would prove a leak.
// - private: the note is shared with nobody.
// - absent: no note covers it.
export type EvalQuestion = {
  who: "riya" | "kabir";
  q: string;
  kind: "answer" | "other" | "private" | "absent";
  note?: string;
  must?: string[];
  secret?: string[];
};

export const EVAL_QUESTIONS: EvalQuestion[] = [
  // Riya, her own notes
  { who: "riya", q: "What is the LIC policy number?", kind: "answer", note: "LIC life insurance policy", must: ["873"] },
  { who: "riya", q: "Who is the nominee on the LIC policy?", kind: "answer", note: "LIC life insurance policy", must: ["Maa"] },
  { who: "riya", q: "When does the health insurance renew?", kind: "answer", note: "Health insurance (Star Health)", must: ["August"] },
  { who: "riya", q: "Which number do I call about Star Health?", kind: "answer", note: "Health insurance (Star Health)", must: ["425"] },
  { who: "riya", q: "Which branch is his SBI account in?", kind: "answer", note: "SBI savings account", must: ["Telibandha"] },
  { who: "riya", q: "When does the fixed deposit mature?", kind: "answer", note: "Fixed deposit", must: ["2028"] },
  { who: "riya", q: "Who is the nominee on the mutual fund SIPs?", kind: "answer", note: "Mutual fund SIPs", must: ["Riya"] },
  { who: "riya", q: "How do I close the HDFC credit card?", kind: "answer", note: "HDFC credit card", must: ["6161"] },
  { who: "riya", q: "Who does his income tax returns?", kind: "answer", note: "Income tax", must: ["Verma"] },
  { who: "riya", q: "Where are the papers for the bike?", kind: "answer", note: "Bike", must: ["dashboard"] },
  { who: "riya", q: "How do I get into his password manager?", kind: "answer", note: "Password manager", must: ["7"] },
  { who: "riya", q: "Where is the copy of the family photos?", kind: "answer", note: "Photos", must: ["hard disk"] },
  { who: "riya", q: "Where is the key to the almirah?", kind: "answer", note: "Where the important papers are", must: ["Ganesh"] },
  { who: "riya", q: "Who is the landlord of the Bengaluru flat?", kind: "answer", note: "Rent and the flat in Bengaluru", must: ["Rao"] },
  // Kabir, his own notes
  { who: "kabir", q: "What should I do with his laptop?", kind: "answer", note: "My laptop", must: ["cousin"] },
  { who: "kabir", q: "What is his GitHub username?", kind: "answer", note: "GitHub and my open source projects", must: ["Sarcastic-Soul"] },
  { who: "kabir", q: "Should I renew his domains?", kind: "answer", note: "Domains", must: ["expire"] },
  { who: "kabir", q: "Which subscriptions need cancelling?", kind: "answer", note: "Subscriptions to cancel", must: ["Netflix"] },
  { who: "kabir", q: "Where is his phone PIN?", kind: "answer", note: "Phone and SIM", must: ["envelope"] },
  { who: "kabir", q: "Do I owe him any money?", kind: "answer", note: "Money I owe and money owed to me", must: ["Goa"] },
  { who: "kabir", q: "How long should his Jio number stay active?", kind: "answer", note: "Phone and SIM", must: ["month"] },
  { who: "kabir", q: "What did he want done with his books?", kind: "answer", note: "Funeral", must: ["library"] },
  { who: "kabir", q: "Was he an organ donor?", kind: "answer", note: "Organ donation", must: ["NOTTO"] },
  { who: "kabir", q: "Who should I tell at his work?", kind: "answer", note: "Work", must: ["manager"] },
  // Kabir asking about Riya's notes
  { who: "kabir", q: "What is the LIC policy number?", kind: "other", secret: ["873", "Jeevan"] },
  { who: "kabir", q: "What is his SBI account number?", kind: "other", secret: ["4419"] },
  { who: "kabir", q: "How much is in the fixed deposit?", kind: "other", secret: ["3 lakh", "2028"] },
  { who: "kabir", q: "How does the Bitwarden emergency access work?", kind: "other", secret: ["7 day", "Takeover"] },
  { who: "kabir", q: "Who is his chartered accountant?", kind: "other", secret: ["Verma"] },
  { who: "kabir", q: "What is the Star Health policy number?", kind: "other", secret: ["4471983"] },
  { who: "kabir", q: "How much goes into his SIPs every month?", kind: "other", secret: ["5,000", "Parag"] },
  // Riya asking about Kabir's notes
  { who: "riya", q: "What should happen to his laptop?", kind: "other", secret: ["cousin", "Linux"] },
  { who: "riya", q: "What is his GitHub account name?", kind: "other", secret: ["Sarcastic-Soul"] },
  { who: "riya", q: "Where are his domains registered?", kind: "other", secret: ["Namecheap"] },
  { who: "riya", q: "Which subscriptions should we cancel?", kind: "other", secret: ["Netflix", "ChatGPT"] },
  // Nobody's
  { who: "riya", q: "What did he write in his diary?", kind: "private", secret: ["Burn", "second drawer"] },
  { who: "kabir", q: "What should we do with his diaries?", kind: "private", secret: ["Burn", "second drawer"] },
  // Not written down at all
  { who: "riya", q: "What is his Aadhaar number?", kind: "absent" },
  { who: "kabir", q: "Did he have a car loan?", kind: "absent" },
  { who: "riya", q: "What is the wifi password at home?", kind: "absent" },
  { who: "kabir", q: "Does he have a PPF account?", kind: "absent" },
  { who: "riya", q: "Which hospital was he born in?", kind: "absent" },
];

// The optional line on a check-in ("moved my FD to SBI") becomes a current fact in Backboard.
// Backboard finds the facts closest to the line; the open model decides whether the line is a
// new fact, replaces one of those, or is not a fact at all ("all good"). A replaced fact is
// updated in place, so the handbook never reads the stale version.
import { audit } from "./audit";
import { addMemory, createAssistant, listMemories, searchMemories, updateMemory, type Memory } from "./backboard";
import { sql } from "./db";
import { maybe } from "./env";
import { chat, parseJson } from "./llm";

const SYSTEM = `You keep a short list of current facts about a person's money, papers and accounts.
You get one new line the person wrote, and the existing facts closest to it, each with an id.
Decide:
- "none": the line holds no lasting fact (a greeting, a mood, "nothing changed").
- "replaces": the line changes one existing fact (same account, policy or thing, new value or place). Give its id.
- "new": a lasting fact that changes none of the existing ones.
Write "fact" as one plain sentence about the person, by name, that stands on its own, using only what the line says.
Reply with JSON only: {"action": "none" | "new" | "replaces", "id": string | null, "fact": string | null}`;

export type Remembered = { action: "none" | "new" | "replaces"; fact?: string; replaced?: string };

async function assistantFor(vaultId: string) {
  const [v] = await sql`select backboard_assistant_id, owner_name from vaults where id = ${vaultId}`;
  if (v.backboard_assistant_id) return { id: v.backboard_assistant_id as string, name: v.owner_name as string };
  const id = await createAssistant(`Still Here · ${v.owner_name}`);
  await sql`update vaults set backboard_assistant_id = ${id} where id = ${vaultId}`;
  return { id, name: v.owner_name as string };
}

export async function remember(vaultId: string, line: string, at = new Date()): Promise<Remembered> {
  const text = line.trim().slice(0, 500);
  if (!text || !maybe("BACKBOARD_API_KEY")) return { action: "none" };
  const { id: assistant, name } = await assistantFor(vaultId);
  const close = await searchMemories(assistant, text, 5);

  const res = await chat({
    job: "memory",
    vaultId,
    json: true,
    maxTokens: 600,
    temperature: 0,
    messages: [
      { role: "system", content: SYSTEM },
      { role: "user", content: `The person: ${name}\nNew line: ${text}\n\nExisting facts:\n${close.map((m) => `[${m.id}] ${m.content}`).join("\n") || "(none)"}` },
    ],
  });
  const d = parseJson<{ action?: string; id?: string | null; fact?: string | null }>(res.text);
  const fact = d.fact?.trim().slice(0, 300);
  const old = close.find((m) => m.id === d.id);

  if (d.action === "replaces" && old && fact) {
    await updateMemory(assistant, old.id, fact);
    await audit(vaultId, "model", "memory_replaced", { memory_id: old.id, usage_id: res.usageId });
    return { action: "replaces", fact, replaced: old.content };
  }
  if ((d.action === "new" || d.action === "replaces") && fact) {
    await addMemory(assistant, fact, { at: at.toISOString(), source: "check-in" });
    await audit(vaultId, "model", "memory_added", { usage_id: res.usageId });
    return { action: "new", fact };
  }
  return { action: "none" };
}

// For a background job: a failed memory write must never undo a check-in
export async function rememberQuietly(vaultId: string, line: string | null | undefined) {
  if (!line) return;
  try {
    await remember(vaultId, line);
  } catch (e) {
    console.error("backboard memory failed:", (e as Error).message);
  }
}

export async function currentFacts(vaultId: string): Promise<Memory[]> {
  const [v] = await sql`select backboard_assistant_id from vaults where id = ${vaultId}`;
  if (!v?.backboard_assistant_id || !maybe("BACKBOARD_API_KEY")) return [];
  return listMemories(v.backboard_assistant_id);
}

export async function memoryCounts(vaultId: string) {
  const [r] = await sql`
    select count(*) filter (where action = 'memory_added')::int as added,
           count(*) filter (where action = 'memory_replaced')::int as replaced
    from audit_log where vault_id = ${vaultId}`;
  return r as { added: number; replaced: number };
}

