## The video plan

```jsonc
{
  "voice": "af_heart",            // Kokoro voice
  "speed": 1.0,
  "lexicon": { "CMC": "C M C" },  // pronunciation fixes, whole word, case-sensitive
  "sfx": true,                    // clicks, typing, pops, whooshes (assets/sfx/); false for none
  "captions": false,              // true: burn subtitles in at the bottom center (see "Captions")
  "theme": { "preset": "clean", "accent": "#10b981" },  // the look of every part (see "Theme" below)
  "hook": {                       // optional story hook, drawn in code (remotion/src/Hook.tsx)
    "look": {                     // shared with the outro
      "skin": "#e0ac69",          // fills the whole drawing (the art is black ink + one fill)
      "hairStyle": "Short"        // Open Peeps hair: Short, Long, Afro, Bun, Hijab, Beanie, ...
      // optional: "accessory": "GlassRound", "facialHair": "Full" (lists in common/plan.py)
      // optional: "outfit": "Sweater"  the body/clothes worn in every scene (default "Hoodie"); moods only
      //   change the face, so it is the same person all video. Names are the poses in common/plan.py
    },
    "scenes": [
      {
        "say": "Meet Sam. Every morning, Sam scrolls crypto Twitter.",
        "mood": "happy",          // happy excited curious worried shocked sad angry relieved confident
                                  //   love smug tired awe playful proud embarrassed focused
        // optional: "react": ["curious", "shocked"]  the character moves through these moods during the
        //   narration (face + pose swap with a pop), spread evenly, or "react_at": [1.5, 3] (seconds in)
        // optional: "face": "Awe" to override the mood's face ("pose" swaps the body: it breaks the same-outfit rule)
        "prop": { "kind": "phone", "app": "post", "text": "next 100x :rocket-launch:", "author": "CryptoKing" },
        // Pick the phone screen that matches the script (`app`), so a text isn't drawn as a tweet:
        //   post  {text, author}                      chat  {text, author, reply?, sent?, failed?}
        //   call  {author, text?}  (text = what they say)        notification {text, author = app, meta?, icon?}
        //   email {author, meta = subject, text}      review {stars 1-5, author, text, meta?}
        //   payment {amount, meta?, author?, text?, failed?}     ai {ask, text}      weather {amount, meta, text?, icon?}
        // no emoji in on-screen text: ":name:" draws a Phosphor icon inline (phosphor-icons.com, kebab case)
        // other props: {"kind":"chart","direction":"down","label":"-62%"}, {"kind":"coin","label":"$PEPE"},
        //   {"kind":"alert","text":"...","image":"shots/x.png"} (red, bad news; optional real screenshot
        //   under the text), {"kind":"check","text":"..."} (green, good news),
        //   {"kind":"screenshot","image":"shots/x.png","caption":"..."}, {"kind":"phone","image":"shots/x.png"},
        //   {"kind":"stat","value":"38","of":"400","label":"tickets sold","bad":true} (big number, bar for x of y),
        //   {"kind":"question"}, {"kind":"none"}
        "bubble": "Next 100x!",   // optional speech bubble
        "label": "ONE WEEK LATER" // optional small scene label
        // "say" is always the narrator: the character never talks
      }
    ]
  },
  "title": {                      // optional ~3s title card (remotion/src/Title.tsx), after the hook
    "text": "Incident War Room", "accent": "War Room",   // accent: words drawn highlighted
    "kicker": "Introducing", "tagline": "Every incident, one live page",
    "say": "Every on-call team knows this night. So we built Incident War Room."
    // optional; without it the card is 2.6s of music. Bridge from the hook's problem to the
    // product ("so we built ...") instead of "This is X": right after the hook, a bare name
    // sounds like the name of the problem that was just described.
  },
  "slides": [
    {
      "kicker": "HOW IT WORKS",
      "title": "LLM finds claims. Code checks them.",
      "title_accent": "Code checks them.",   // exact substring of title, highlighted (marker or accent color)
      "bullets": ["3-6 word fragments", "..."],
      "narration": "One or two spoken sentences, about 6-9 seconds.",
      "image": "shots/result.png"            // optional: screenshot shown in a browser frame
      // or "mood": "curious" instead: the hook's character on the slide (no image)
    },
    // Picture slides (no bullets): one idea, very little text,
    // revealed in time with the narration. Mix them with bullet slides.
    { "kicker": "HOW IT WORKS", "title": "...", "narration": "...", "layout": "flow",
      "flow": [{ "label": "Paste a post", "icon": "clipboard-text" }, { "label": "LLM pulls claims", "icon": "robot" },
               { "label": "Verdict + receipts", "icon": "receipt" }] },   // 2-5 steps, labels <= 4 words, arrows drawn on
                                                  // icon: Phosphor name (phosphor-icons.com); left out = step number
    { "kicker": "THE DIFFERENCE", "title": "...", "narration": "...", "layout": "compare",
      "compare": { "before": { "title": "Scrolling X", "items": ["Claims sound like facts", "..."] },
                   "after":  { "title": "With Receipts", "items": ["Each claim tested", "..."] } } },  // 1-4 items each
    // compare sides can show a screenshot too: "after": {"title": "...", "image": "shots/x.png", "items": [...]}
    //   (0 items is fine with an image)
    { "kicker": "BY THE NUMBERS", "title": "...", "narration": "...", "layout": "stat",
      "stats": [{ "value": "4.5s", "label": "per post" }] },      // 1-3 numbers, counted up
    { "kicker": "UNDER THE HOOD", "title": "How it's wired", "narration": "...", "layout": "diagram",
      "diagram": {                // architecture diagram, laid out by elkjs, drawn in the theme
        "direction": "right",     // or "down"
        "groups": [{ "id": "sanity", "label": "Sanity", "logo": "sanity" }],   // dashed boxes around nodes
        "nodes": [                // 2-9, revealed in this order across the narration
          { "id": "app", "label": "Next.js app", "logo": "nextdotjs", "main": true },  // main: accent fill
          { "id": "lake", "label": "Content Lake", "logo": "sanity", "group": "sanity" },
          { "id": "llm", "label": "Groq LLM", "icon": "robot" }
        ],
        "edges": [{ "from": "app", "to": "lake", "label": "mutations" }, { "from": "app", "to": "llm" }]
      } },                        // edges draw on when both ends are shown, then dots flow along them
    { "kicker": "BUILT WITH", "title": "The stack", "narration": "...", "layout": "stack",
      "stack": [{ "label": "Next.js", "logo": "nextdotjs" }, { "label": "Groq LLM", "icon": "robot" }] }  // 2-10 tiles
    // "logo": a Simple Icons slug or title (simpleicons.org; brand color, swapped for the text color when
    // it would vanish on the card). Brands missing there (OpenAI, AWS, Groq) take a Phosphor "icon".
  ],
  "outro": {                      // optional: same character, now using the product, then the end card
    "scenes": [
      { "say": "Now Sam checks every post first.", "mood": "relieved",
        "prop": { "kind": "screenshot", "image": "shots/verdict.png" } }
    ],
    "cta": {
      "title": "Try Receipts now",
      "subtitle": "One line on what it does for the viewer.",
      "url": "your-app.vercel.app",
      "say": "Try Receipts now.",
      "mood": "confident",        // default
      "qr": [{ "url": "https://your-app.vercel.app", "label": "Live demo" },
             { "url": "https://github.com/you/app", "label": "GitHub" }]
      // default: one QR code for "url"; false for none
    }
  },
  "youtube": {                    // optional: everything here has a default from the rest of the plan
    "title": "...",               // default: title text + tagline
    "description": "...",         // default: tagline + the end card's subtitle
    "links": [{ "label": "GitHub", "url": "https://github.com/you/app" }],  // the live url is always first
    "thumbnail": {                // all optional
      "text": "Is your incident really fixed?", "accent": "really",   // 2-6 big words: a hook or a question,
                                  //   not just the name (default: the tagline if short, else the name)
      "image": "shots/pending.png",   // a real screenshot (a snap): the "product" layout
      "layout": "product",        // product (big screenshot, character in a corner) | question (big ? marks) |
                                  //   reaction (big words + big character); default: product with an image (when none is given, the first shots/*.png from a snap is used), else reaction
      "mood": "awe"               // default per layout: awe / curious / excited. Scared faces read as fear of the product
    }                             // the product's name goes in a small badge when the text isn't the name
  },
  "demo": {
    "url": "https://your-app.vercel.app",
    "viewport": [1280, 720],      // CSS px
    "scale": 1.5,                 // capture size per CSS px: 1.5 = 1920x1080 frames; 2 = 2560x1440,
                                  //   sharper when zoomed in, about 40% slower demo render
    "color_scheme": "light",
    "auto_zoom": false,           // true (1.5x) or a zoom: lean in on each typed field while typing
    "setup": [ /* actions run before recording starts */ ],
    "scenes": [
      {
        "say": "Narration for this scene.",
        "say_at": "start",        // or "end": run the actions first, then talk
        "do": [ /* actions */ ],
        "step": "Paste a post",   // optional: label in the side panel's step list
        "panel": { "title": "...", "text": "...", "bullets": ["..."] },  // optional side panel card
        "split": true,            // optional: show the "peer" browser next to this one (needs "peer")
        "cameo": { "mood": "excited", "text": "No refresh!" }  // optional: the hook's character pops
                                  //   into a bottom corner for 2.6s ("seconds", "side": "left"|"right")
      }
    ],
